# Tool Input/Output Schema Registry demo: validate calls, check composability.
import re
SCHEMAS={"resize":{"in":{"width":"int>0","height":"int>0"},"out":["image"]},
         "caption":{"in":{"image":"bytes"},"out":["text"]}}
def validate(tool,args):
    sch=SCHEMAS[tool]["in"]; errs=[]
    for f,rule in sch.items():
        if f not in args: errs.append("missing "+f); continue
        if rule=="int>0" and not (isinstance(args[f],int) and args[f]>0): errs.append(f+" must be positive int")
    return errs or ["valid"]
def composable(a,b):
    return bool(set(SCHEMAS[a]["out"])&set(SCHEMAS[b]["in"].keys()) or
               any(o in str(SCHEMAS[b]["in"]) for o in SCHEMAS[a]["out"]))
print(validate("resize",{"width":100,"height":-5}))
print(validate("resize",{"width":100,"height":50}))
print("resize->caption composable:",composable("resize","caption"))

